9	// These tests pin the credential redaction of upstream diagnostics: when a
10	// configuration error reason quotes an upstream address that carries
11	// userinfo, the whole userinfo segment — username and optional password,
12	// colons and percent escapes included — is replaced by "***" while the '@'
13	// separating it from the host is kept, so a saved diagnostic can never leak
14	// the configured credentials. The reason still names the route's 1-based
15	// position, its id, the upstream field and the actual problem, the code
16	// stays invalid_config and the whole config is still rejected.
17	
18	// TestUpstreamUserinfoRedactedInMissingHostReason drives the headline case:
19	// "https://alice:s3cr%40t@:8443/v1" fails the missing-host check, and the
20	// reason must show the address as "https://***@:8443/v1" — never the
21	// username, never the password, encoded or decoded.
22	func TestUpstreamUserinfoRedactedInMissingHostReason(t *testing.T) {
23		cases := []struct {
24			name     string
25			upstream string
26			shown    string   // the address as it must appear in the reason
27			hidden   []string // byte sequences that must not appear anywhere
28		}{
29			{"encoded password", "https://alice:s3cr%40t@:8443/v1", "https://***@:8443/v1", []string{"alice", "s3cr%40t", "s3cr@t"}},
30			{"plain userinfo", "http://alice:secret@:8080/base", "http://***@:8080/base", []string{"alice", "secret"}},
31			{"username only", "http://alice@:8080/base", "http://***@:8080/base", []string{"alice"}},
32			{"empty password", "http://alice:@:8080/base", "http://***@:8080/base", []string{"alice"}},
33			{"colons in password", "http://alice:s3:cr3t@:8080/base", "http://***@:8080/base", []string{"alice", "s3:cr3t"}},
34			{"multiple at signs in authority", "https://al@ice:s3cr%40t@:8443/v1", "https://***@:8443/v1", []string{"al@ice", "s3cr%40t"}},
35			{"at sign in base path is not userinfo", "https://alice:pw9@:8443/v1@x", "https://***@:8443/v1@x", []string{"alice", "pw9"}},
36			{"userinfo reduced to empty authority", "http://svc@/base", "http://***@/base", []string{"svc"}},
37		}
38		for _, tc := range cases {
39			t.Run(tc.name, func(t *testing.T) {
40				src := `{"routes":[
41				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
42				  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
43				]}`
44				cfg, f := ParseConfig([]byte(src))
45				if f == nil || f.Code != "invalid_config" {
46					t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", tc.upstream, cfg, f)
47				}
48				if cfg != nil {
49					t.Fatalf("a rejected config must not be returned, got %+v", cfg)
50				}
51				for _, want := range []string{"route 2", `"admin"`, "upstream", "missing a host", `"` + tc.shown + `"`} {
52					if !strings.Contains(f.Reason, want) {
53						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
54					}
55				}
56				for _, leaked := range tc.hidden {
57					if strings.Contains(f.Reason, leaked) {
58						t.Fatalf("reason = %q leaks userinfo %q", f.Reason, leaked)
59					}
60				}
61			})
62		}
63	}
64	
65	// TestUpstreamUserinfoRedactedInHostAndParseReasons covers the other
66	// diagnostics that quote the address: the extra-colon host rule and the
67	// generic URL parse error (an invalid escape). The attached parse error
68	// must not repeat the original address either.
69	func TestUpstreamUserinfoRedactedInHostAndParseReasons(t *testing.T) {
70		cases := []struct {
71			name     string
72			upstream string
73			want     []string
74			hidden   []string
75		}{
76			{
77				name:     "extra colon after userinfo",
78				upstream: "https://alice:s3:cr3t@api:internal:8080/base",
79				want:     []string{"route 1", `"api"`, "upstream", "more than one colon", `"https://***@api:internal:8080/base"`},
80				hidden:   []string{"alice", "s3:cr3t"},
81			},
82			{
83				name:     "invalid escape in userinfo",
84				upstream: "https://alice:p%4@host.internal/",
85				want:     []string{"route 1", `"api"`, "upstream", "invalid percent escape in its userinfo", `"https://***@host.internal/"`},
86				hidden:   []string{"alice", "p%4", `"%4"`},
87			},
88			{
89				name:     "invalid escape in host with userinfo",
90				upstream: "https://alice:secret@ho%zzst/",
91				want:     []string{"route 1", `"api"`, "upstream", "not a valid URL", `parse "https://***@ho%zzst/"`},
92				hidden:   []string{"alice", "secret"},
93			},
94		}
95		for _, tc := range cases {
96			t.Run(tc.name, func(t *testing.T) {
97				src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + tc.upstream + `"}]}`
98				cfg, f := ParseConfig([]byte(src))
99				if f == nil || f.Code != "invalid_config" {
100					t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", tc.upstream, cfg, f)
101				}
102				for _, want := range tc.want {
103					if !strings.Contains(f.Reason, want) {
104						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
105					}
106				}
107				for _, leaked := range tc.hidden {
108					if strings.Contains(f.Reason, leaked) {
109						t.Fatalf("reason = %q leaks userinfo %q", f.Reason, leaked)
110					}
111				}
112			})
113		}
114	}
