116	// TestUpstreamWithoutUserinfoKeepsExistingDiagnostics pins that an address
117	// without userinfo is shown in full exactly as before — redaction must not
118	// rewrite diagnostics that carry no credentials.
119	func TestUpstreamWithoutUserinfoKeepsExistingDiagnostics(t *testing.T) {
120		cases := []struct {
121			name     string
122			upstream string
123			want     string
124		}{
125			{"bare port", "http://:8080/base", `upstream "http://:8080/base" is missing a host`},
126			{"at sign only in base path", "http://:8080/v1@x", `upstream "http://:8080/v1@x" is missing a host`},
127			{"extra colon", "http://api:internal:8080/base", `upstream "http://api:internal:8080/base" has an unbracketed host part`},
128		}
129		for _, tc := range cases {
130			t.Run(tc.name, func(t *testing.T) {
131				src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + tc.upstream + `"}]}`
132				_, f := ParseConfig([]byte(src))
133				if f == nil || f.Code != "invalid_config" {
134					t.Fatalf("upstream %q: got %+v, want invalid_config", tc.upstream, f)
135				}
136				if !strings.Contains(f.Reason, tc.want) {
137					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
138				}
139				if strings.Contains(f.Reason, "***") {
140					t.Fatalf("reason = %q must not redact an address without userinfo", f.Reason)
141				}
142			})
143		}
144	}
