146	// TestValidUserinfoUpstreamUnchanged pins that redaction only touches
147	// failure diagnostics: a legal upstream with userinfo is still accepted,
148	// the resolved upstreamURL keeps the original address byte for byte
149	// (percent escapes included) and the stored config keeps the userinfo.
150	func TestValidUserinfoUpstreamUnchanged(t *testing.T) {
151		src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"https://alice:s3cr%40t@host.internal:8443/v1"}]}`
152		cfg := mustConfig(t, src)
153		res := resolveJSON(t, cfg, `{"method":"GET","target":"/x"}`)
154		if want := "https://alice:s3cr%40t@host.internal:8443/v1/x"; res.UpstreamURL != want {
155			t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, want)
156		}
157		if cfg.Routes[0].Upstream != "https://alice:s3cr%40t@host.internal:8443/v1" {
158			t.Errorf("stored upstream = %q, want the original address with userinfo", cfg.Routes[0].Upstream)
159		}
160	}
