162	// TestUpstreamUserinfoBadEscapeDedicatedReason is the headline fix: when
163	// the password (or username) itself is an illegal percent escape such as
164	// https://alice:%zz@host.internal/base, url.Parse's reason would quote the
165	// credential verbatim (invalid URL escape "%zz"). The config reader must
166	// instead return invalid_config with a reason that locates the route by its
167	// 1-based position, id and the upstream field, shows the address as
168	// "scheme://***@host/..." (whole username and optional password hidden,
169	// '@' and the rest kept) and never repeats the malformed fragment or any
170	// other byte of the credential. No config is returned.
171	func TestUpstreamUserinfoBadEscapeDedicatedReason(t *testing.T) {
172		cases := []struct {
173			name     string
174			upstream string
175			shown    string   // redacted address that must appear quoted
176			hidden   []string // bytes that must not appear anywhere in the reason
177		}{
178			{"illegal escape in password", "https://alice:%zz@host.internal/base", "https://***@host.internal/base", []string{"alice", "%zz", `"%zz"`}},
179			{"truncated escape at password end", "https://alice:pw%2@host.internal/base", "https://***@host.internal/base", []string{"alice", "pw%2", `"%2"`}},
180			{"truncated escape mid password", "https://alice:p%4@host.internal/", "https://***@host.internal/", []string{"alice", "p%4", `"%4"`}},
181			{"lone percent in password", "https://alice:pw%@host/", "https://***@host/", []string{"alice", "pw%", `"%"`}},
182			{"illegal escape in username with password", "https://%zz:secret@host.internal/base", "https://***@host.internal/base", []string{"secret", "%zz", `"%zz"`}},
183			{"illegal escape in username only", "https://al%zz@host.internal/base", "https://***@host.internal/base", []string{"al%zz", `"%zz"`}},
184			{"username-only truncated escape", "http://u%4@host/base", "http://***@host/base", []string{"u%4", `"%4"`}},
185			{"empty password then bad username", "https://%zz:@host/", "https://***@host/", []string{"%zz", `"%zz"`}},
186			{"uppercase scheme spelling", "HTTPS://alice:%zz@host/", "HTTPS://***@host/", []string{"alice", "%zz", `"%zz"`}},
187			{"http scheme", "http://alice:%zz@host/", "http://***@host/", []string{"alice", "%zz", `"%zz"`}},
188		}
189		for _, tc := range cases {
190			t.Run(tc.name, func(t *testing.T) {
191				src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + tc.upstream + `"}]}`
192				cfg, f := ParseConfig([]byte(src))
193				if f == nil || f.Code != "invalid_config" {
194					t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", tc.upstream, cfg, f)
195				}
196				if cfg != nil {
197					t.Fatalf("a rejected config must not be returned, got %+v", cfg)
198				}
199				for _, want := range []string{"route 1", `"api"`, "upstream", "invalid percent escape in its userinfo", `"` + tc.shown + `"`} {
200					if !strings.Contains(f.Reason, want) {
201						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
202					}
203				}
204				for _, leaked := range tc.hidden {
205					if strings.Contains(f.Reason, leaked) {
206						t.Fatalf("reason = %q leaks credential fragment %q", f.Reason, leaked)
207					}
208				}
209			})
210		}
211	}
212	
213	// TestUpstreamUserinfoBadEscapeRejectsWholeConfig pins that a bad
214	// userinfo escape rejects the whole configuration even when the request
215	// only matches a different, legal route: ParseConfig hands back no config at
216	// all, and the reason locates the offending later route by its 1-based
217	// position and id.
218	func TestUpstreamUserinfoBadEscapeRejectsWholeConfig(t *testing.T) {
219		src := `{"routes":[
220		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
221		  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"https://alice:%zz@host.internal/base"}
222		]}`
223		cfg, f := ParseConfig([]byte(src))
224		if f == nil || f.Code != "invalid_config" {
225			t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
226		}
227		if cfg != nil {
228			t.Fatalf("the whole config must be rejected even though /api only hits route 1, got %+v", cfg)
229		}
230		for _, want := range []string{"route 2", `"admin"`, "upstream", `"https://***@host.internal/base"`} {
231			if !strings.Contains(f.Reason, want) {
232				t.Fatalf("reason = %q, want substring %q", f.Reason, want)
233			}
234		}
235		for _, leaked := range []string{"alice", "%zz"} {
236			if strings.Contains(f.Reason, leaked) {
237				t.Fatalf("reason = %q leaks %q", f.Reason, leaked)
238			}
239		}
240	}
241	
242	// TestUpstreamHostAndPathEscapesKeepTheirDiagnostics pins the other side of
243	// the redaction boundary: when the userinfo is legal and the malformed
244	// escape actually belongs to the host or base path, the existing specific
245	// diagnostic — including its fragment — is preserved verbatim, even when the
246	// host or path text is identical to a string that would be a credential,
247	// and an '@' inside the base path must not be read as userinfo. Only the
248	// credentials are hidden.
249	func TestUpstreamHostAndPathEscapesKeepTheirDiagnostics(t *testing.T) {
250		cases := []struct {
251			name     string
252			upstream string
253			shown    string
254			keep     []string // diagnostics that must survive, fragment included
255			hidden   []string // only the credentials are hidden
256		}{
257			{
258				name:     "illegal escape in host with legal userinfo",
259				upstream: "https://alice:secret@ho%zzst/",
260				shown:    "https://***@ho%zzst/",
261				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
262				hidden:   []string{"alice", "secret"},
263			},
264			{
265				name:     "illegal escape in base path with legal userinfo",
266				upstream: "https://alice:pw9@host.internal/base%zz/x",
267				shown:    "https://***@host.internal/base%zz/x",
268				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
269				hidden:   []string{"alice", "pw9"},
270			},
271			{
272				name:     "at sign in base path is not userinfo",
273				upstream: "https://alice:pw9@host.internal/v1@x%zz",
274				shown:    "https://***@host.internal/v1@x%zz",
275				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`, "/v1@x%zz"},
276				hidden:   []string{"alice", "pw9"},
277			},
278			{
279				name:     "illegal escape in host without userinfo stays whole",
280				upstream: "http://ho%zzst/",
281				shown:    "http://ho%zzst/",
282				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
283				hidden:   nil,
284			},
285			{
286				name:     "illegal escape in base path without userinfo stays whole",
287				upstream: "http://host.internal/base%zz/x",
288				shown:    "http://host.internal/base%zz/x",
289				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`, "host.internal"},
290				hidden:   nil,
291			},
292		}
293		for _, tc := range cases {
294			t.Run(tc.name, func(t *testing.T) {
295				src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + tc.upstream + `"}]}`
296				cfg, f := ParseConfig([]byte(src))
297				if f == nil || f.Code != "invalid_config" {
298					t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", tc.upstream, cfg, f)
299				}
300				if !strings.Contains(f.Reason, `parse "`+tc.shown+`"`) {
301					t.Fatalf("reason = %q, want redacted address %q", f.Reason, tc.shown)
302				}
303				for _, want := range tc.keep {
304					if !strings.Contains(f.Reason, want) {
305						t.Fatalf("reason = %q, want host/path diagnostic %q preserved", f.Reason, want)
306					}
307				}
308				for _, leaked := range tc.hidden {
309					if strings.Contains(f.Reason, leaked) {
310						t.Fatalf("reason = %q leaks credential %q", f.Reason, leaked)
311					}
312				}
313			})
314		}
315	}
316	
317	// TestUpstreamUserinfoBadEscapeNonHTTPSchemeStillRedacted pins the
318	// defense-in-depth path: a non-http scheme with a bad userinfo escape keeps
319	// the generic "not a valid URL" wording (the dedicated field reason is the
320	// http/https contract) but still never quotes the credential fragment.
321	func TestUpstreamUserinfoBadEscapeNonHTTPSchemeStillRedacted(t *testing.T) {
322		src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"ftp://alice:%zz@host.internal/base"}]}`
323		cfg, f := ParseConfig([]byte(src))
324		if f == nil || f.Code != "invalid_config" {
325			t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
326		}
327		for _, want := range []string{"not a valid URL", `parse "ftp://***@host.internal/base"`} {
328			if !strings.Contains(f.Reason, want) {
329				t.Fatalf("reason = %q, want substring %q", f.Reason, want)
330			}
331		}
332		for _, leaked := range []string{"alice", "%zz"} {
333			if strings.Contains(f.Reason, leaked) {
334				t.Fatalf("reason = %q leaks credential fragment %q", f.Reason, leaked)
335			}
336		}
337	}
338	
339	// TestValidUserinfoUpstreamSurvivesSaveRoundTrip pins that diagnostic
340	// redaction never reaches persisted configuration: a legal credential is
341	// accepted and re-marshalled with the username, password and percent
342	// encoding byte for byte, and the re-parsed config resolves identically.
343	func TestValidUserinfoUpstreamSurvivesSaveRoundTrip(t *testing.T) {
344		src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"https://alice:s3cr%40t@host.internal/v1"}]}`
345		cfg := mustConfig(t, src)
346		saved, err := json.Marshal(cfg)
347		if err != nil {
348			t.Fatalf("marshal: %v", err)
349		}
350		if !strings.Contains(string(saved), `"upstream":"https://alice:s3cr%40t@host.internal/v1"`) {
351			t.Fatalf("saved config lost userinfo or percent encoding: %s", saved)
352		}
353		reparsed := mustConfig(t, string(saved))
354		res := resolveJSON(t, reparsed, `{"method":"GET","target":"/x"}`)
355		if want := "https://alice:s3cr%40t@host.internal/v1/x"; res.UpstreamURL != want {
356			t.Fatalf("reparsed upstreamURL = %q, want %q", res.UpstreamURL, want)
357		}
358	}
